    } 
    vector&lt;int&gt;ans(n,1);
    for(int i=1;i&lt;n;i++){
        ans[i]=ans[i-1]*nums[i-1];
    }
    int right=1;
    for(int i=n-1;i&gt;=0;i--){
    ans[i]=ans[i]*right;
    right=nums[i]*right;
    }
