</code></pre> ​本​喵​依旧​解释一下​代码​：</p> <p>​我们​用​的​char :s ​依旧​是​存储​不同​的​数组​</p> <p>​比如说​我们​输入​1 apple</p> <p>a-'a'=0; tr[0][0]=1; p=1;</p> <p>p-'a'=15; tr[1][15]=2; p=2;</p> <p>p-'a'=15; tr[2][15]=3; p=3;</p> <p>l-'a'=11; tr[3][11]=4; p=4;</p> <p>e-'a'=4; tr[4][4]=5; p=5;</p> <p>tr[p].end=true;</p> <p>p=0;</p> ​字典​树​.cpp<pre><code>#include&lt;bits/stdc++.h&gt;
using namespace std;

const int N=1000010;
struct Node{
    int cnt;
    int nd[26];
}tr[N];
int len;
void insert(string s){
    int p=0;
    for(int i=0;i&lt;s.size();i++){
        int c=s[i]-'a';
        if(tr[p].nd[c]==0){
            tr[p].nd[c]=++len;
        }
        p=tr[p].nd[c];
    }
    tr[p].cnt++;
}

bool search(string s){
    int p=0;
    for(int i=0;i&lt;s.size();i++){
        int c=s[i]-'a';
        if(tr[p].nd[c]==0){
            return false;
        }
        p=tr[p].nd[c];
    }
    return tr[p].cnt&gt;0;
}
int main(){
